CREATE TABLE `tasks` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`title` VARCHAR(200) NOT NULL,`description` TEXT NOT NULL,`status` ENUM('todo','in_progress','completed','cancelled') NOT NULL DEFAULT 'todo',`priority` ENUM('low','normal','high','critical') NOT NULL DEFAULT 'normal',`assignee_id` CHAR(36) CHARACTER SET ascii NOT NULL,`source_type` ENUM('manual','sourcing_purchase') NOT NULL DEFAULT 'manual',`source_ref_id` CHAR(36) CHARACTER SET ascii NULL,`due_at` DATETIME(3) NULL,`completed_at` DATETIME(3) NULL,`created_by` CHAR(36) CHARACTER SET ascii NOT NULL,`version` INT UNSIGNED NOT NULL DEFAULT 1,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_tasks_source`(`organization_id`,`workspace_id`,`source_type`,`source_ref_id`),KEY `idx_tasks_scope_status_time`(`organization_id`,`workspace_id`,`status`,`updated_at`),KEY `idx_tasks_assignee_due`(`organization_id`,`workspace_id`,`assignee_id`,`due_at`),CONSTRAINT `fk_tasks_org` FOREIGN KEY(`organization_id`) REFERENCES `organizations`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_tasks_workspace` FOREIGN KEY(`workspace_id`) REFERENCES `workspaces`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_tasks_assignee` FOREIGN KEY(`assignee_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_tasks_creator` FOREIGN KEY(`created_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `task_comments` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`task_id` CHAR(36) CHARACTER SET ascii NOT NULL,`body` VARCHAR(2000) NOT NULL,`created_by` CHAR(36) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),KEY `idx_task_comments_task_time`(`organization_id`,`workspace_id`,`task_id`,`created_at`),CONSTRAINT `fk_task_comments_task` FOREIGN KEY(`task_id`) REFERENCES `tasks`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_task_comments_creator` FOREIGN KEY(`created_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `task_events` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`task_id` CHAR(36) CHARACTER SET ascii NOT NULL,`event_type` VARCHAR(80) CHARACTER SET ascii NOT NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`payload_json` JSON NOT NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),KEY `idx_task_events_scope_task`(`organization_id`,`workspace_id`,`task_id`,`created_at`),KEY `idx_task_events_trace`(`trace_id`),CONSTRAINT `fk_task_events_task` FOREIGN KEY(`task_id`) REFERENCES `tasks`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `task_operations` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`route_key` VARCHAR(160) CHARACTER SET ascii NOT NULL,`idempotency_key` VARCHAR(128) CHARACTER SET ascii NOT NULL,`task_id` CHAR(36) CHARACTER SET ascii NOT NULL,`result_json` JSON NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_task_operations`(`actor_id`,`route_key`,`idempotency_key`),CONSTRAINT `fk_task_operations_task` FOREIGN KEY(`task_id`) REFERENCES `tasks`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ALTER TABLE `sourcing_outbox` MODIFY `status` ENUM('queued','leased','published','dead_letter') NOT NULL DEFAULT 'queued',ADD COLUMN `leased_by` VARCHAR(120) NULL AFTER `status`,ADD COLUMN `leased_at` DATETIME(3) NULL AFTER `leased_by`,ADD COLUMN `lease_expires_at` DATETIME(3) NULL AFTER `leased_at`,ADD KEY `idx_sourcing_outbox_lease` (`lease_expires_at`);
